INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e0cb2ae5-a450-50f1-9a57-1a457ed3c559', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A network uses Ansible to push SNMP community strings to switches. The playbook is run again with the same variables. What is the most likely result or action?$$::text, $$[{"id": "A", "text": "Use IPsec tunnel mode for site-to-site or remote access VPNs.", "is_correct": false}, {"id": "B", "text": "Configure AAA with TACACS+ and a local fallback method list.", "is_correct": false}, {"id": "C", "text": "Update the documentation to match the actual configuration discovered via CDP/LLDP.", "is_correct": false}, {"id": "D", "text": "No changes are made because Ansible is idempotent.", "is_correct": true}]$$::jsonb, $$Given A network uses Ansible to push SNMP community strings to switches. and The playbook is run again with the same variables., the result is: No changes are made because Ansible is idempotent.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security & Automation Fundamentals$$::text, 16.67, '15893e0d25da34e2', true) ON CONFLICT (id) DO NOTHING;
