INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f4a49ec3-61a0-55cf-8786-3fc0d7f95b20', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'apply', $$An IPv6 prefix is 114c:440d:675d:b930::/60. How many /96 subnets can be created?$$::text, $$[{"id": "A", "text": "549755813888", "is_correct": false}, {"id": "B", "text": "274877906944", "is_correct": false}, {"id": "C", "text": "1099511627776", "is_correct": false}, {"id": "D", "text": "137438953472", "is_correct": false}, {"id": "E", "text": "2199023255552", "is_correct": false}, {"id": "F", "text": "68719476736", "is_correct": true}]$$::jsonb, $$A /60 prefix can be split into /96 subnets: 2^(96-60) = 68719476736.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 14.29, '88cabeb555d5a616', true) ON CONFLICT (id) DO NOTHING;
