INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41019377-86b3-5790-bfe8-83a3f7b3718e', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A VM cannot communicate with other VMs in the same VLAN. The VM is connected to a vSwitch port group assigned to a different VLAN. What is the most likely result or action?$$::text, $$[{"id": "A", "text": "The switch floods the frame within the source VLAN.", "is_correct": false}, {"id": "B", "text": "DHCP offers from the untrusted port are dropped.", "is_correct": false}, {"id": "C", "text": "Move the VM to the correct port group or change the port group VLAN.", "is_correct": true}, {"id": "D", "text": "Check routing with 'ip route' and ARP with 'ip neigh'.", "is_correct": false}]$$::jsonb, $$Given A VM cannot communicate with other VMs in the same VLAN. and The VM is connected to a vSwitch port group assigned to a different VLAN., the result is: Move the VM to the correct port group or change the port group VLAN.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$1.0 Network Fundamentals$$::text, 14.29, '42468c41946f14d7', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2fd72a2a-7cda-5735-b48d-0f06a1e22224', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'understand', $$What is the key difference between OSPFv2 and OSPFv3?$$::text, $$[{"id": "A", "text": "LACP is IEEE standard; PAgP is Cisco proprietary.", "is_correct": false}, {"id": "B", "text": "AH provides integrity; ESP provides encryption and integrity.", "is_correct": false}, {"id": "C", "text": "OSPFv2 is for IPv4; OSPFv3 is for IPv6 and uses link-local addresses.", "is_correct": true}, {"id": "D", "text": "Type 1 runs directly on hardware; Type 2 runs on a host OS.", "is_correct": false}]$$::jsonb, $$OSPFv2 is for IPv4; OSPFv3 is for IPv6 and uses link-local addresses.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$5.0 Security & Automation Fundamentals$$::text, 16.67, '8c74fd963fde0f19', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

-- +goose StatementBegin
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('77f23617-f95d-58ff-a028-e132a9d6cd05', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'single-choice', 3, 'analyze', $$A switch has Rapid PVST+ enabled and a new port is connected to a host. The port is not configured with PortFast. What is the most likely result or action?$$::text, $$[{"id": "A", "text": "Verify the link-local gateway is reachable and routing is configured for the global prefix.", "is_correct": false}, {"id": "B", "text": "The port goes through listening and learning states before forwarding, causing temporary connectivity delay.", "is_correct": true}, {"id": "C", "text": "On a broadcast segment, full adjacencies are only formed with DR/BDR; 2-WAY is normal for DROTHERs.", "is_correct": false}, {"id": "D", "text": "The floating static route remains inactive while the primary route is present.", "is_correct": false}]$$::jsonb, $$Given A switch has Rapid PVST+ enabled and a new port is connected to a host. and The port is not configured with PortFast., the result is: The port goes through listening and learning states before forwarding, causing temporary connectivity delay.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$2.0 Network Access$$::text, 20.0, '9611ade452a848f8', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

