INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6a7be383-3165-5b6e-9798-193e7f255885', 'b0000000-0000-0000-0000-000000000003', 'a0000000-0000-0000-0000-000000000006', 'multiple-choice', 3, 'analyze', $$Which statements about SFTP and SCP are true? (Choose two.)$$::text, $$[{"id": "A", "text": "They run over SSH", "is_correct": true}, {"id": "B", "text": "They are unencrypted", "is_correct": false}, {"id": "C", "text": "They encrypt data in transit", "is_correct": true}, {"id": "D", "text": "They require TFTP", "is_correct": false}, {"id": "E", "text": "They use UDP", "is_correct": false}]$$::jsonb, $$SFTP and SCP are secure file transfers over SSH. TFTP and FTP are unencrypted.$$::text, $${"https://learningcontent.cisco.com/documents/marketing/exam-topics/200-301-CCNA-v1.1.pdf"}$$::text[], $$4.0 IP Services$$::text, 14.29, 'eac39cc36abd0cb1', true) ON CONFLICT (id) DO NOTHING;
-- +goose StatementEnd

